<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingNotifications extends Page{protected static ?string $navigationIcon='heroicon-o-bell';protected static ?string $navigationLabel='Уведомления';protected static ?string $navigationGroup='Воспитательная работа';protected static string $view='filament.pages.upbringing-notifications';public array $rows=[];public function mount():void{$this->rows=DB::table('upbringing_notifications')->where('user_id',auth()->id())->orderByRaw('read_at is not null')->orderByDesc('created_at')->limit(100)->get()->map(fn($x)=>(array)$x)->all();}public function markRead($id):void{DB::table('upbringing_notifications')->where(['id'=>$id,'user_id'=>auth()->id()])->update(['read_at'=>now(),'updated_at'=>now()]);$this->mount();}}
